setTimeout(() => {
  document.querySelectorAll('h1, h2, h3, h4, h5, p, span, div').forEach(el => {
    if(el.childNodes.length === 1 && el.childNodes[0].nodeType === 3 && el.textContent.includes('Architects & Engineers') && el.textContent.includes('Employees Co-operative')) {
      el.style.textAlign = 'left';
      el.style.whiteSpace = 'pre-wrap';
      el.style.maxWidth = 'none';
      el.style.width = '100%';
      
      let container = el.parentElement;
      if (container) {
        container.style.textAlign = 'left';
        container.style.maxWidth = 'none';
        container.style.width = '100%';
        if (window.getComputedStyle(container).display === 'flex' && window.getComputedStyle(container).flexDirection === 'column') {
          container.style.alignItems = 'flex-start';
        }
        Array.from(container.children).forEach(child => {
           child.style.textAlign = 'left';
        });
      }
    }
  });
}, 1000);



setTimeout(() => {
  document.querySelectorAll('h2').forEach(el => {
    if (el.textContent.includes('Newspaper Cuttings')) {
      const parent = el.closest('section');
      if (parent) {
        const grid = parent.querySelector('.grid.gap-6');
        if (grid) {
          parent.style.display = 'none';
        }
      }
    }
  });
}, 100);
setInterval(() => {
  document.querySelectorAll('h2').forEach(el => {
    if (el.textContent.trim() === 'About the Society') {
      const parentSection = el.closest('section') || el.parentElement.parentElement;
      if (parentSection && !parentSection.id) {
        parentSection.id = 'about';
      }
    }
  });
}, 500);
